\u0647 \u06a9\u0646\u06cc\u062f."],"The first 10% of the content should contain the Focus Keyword preferably at the beginning.":["10% \u0627\u0648\u0644 \u0645\u0637\u0627\u0644\u0628 \u0628\u0627\u06cc\u062f \u062f\u0631 \u0627\u0628\u062a\u062f\u0627 \u0634\u0627\u0645\u0644 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u0628\u0627\u0634\u062f."],"Focus Keyword found in the content.":["\u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0645\u062d\u062a\u0648\u0627 \u067e\u06cc\u062f\u0627 \u0634\u062f."],"Focus Keyword doesn't appear in the content.":["\u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0645\u062d\u062a\u0648\u0627 \u0638\u0627\u0647\u0631 \u0646\u0645\u06cc \u0634\u0648\u062f."],"Use Focus Keyword in the content.":["\u062f\u0631 \u0645\u062d\u062a\u0648\u0627 \u0627\u0632 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f."],"It is recommended to make the focus keyword appear in the post content too.":["\u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc \u0634\u0648\u062f \u06a9\u0647 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0645\u062d\u062a\u0648\u0627\u06cc \u0646\u0648\u0634\u062a\u0647 \u0646\u06cc\u0632 \u0638\u0627\u0647\u0631 \u0634\u0648\u062f."],"Minimum recommended content length should be 600 words.":["\u062d\u062f\u0627\u0642\u0644 \u0637\u0648\u0644 \u0645\u062d\u062a\u0648\u0627\u06cc \u067e\u06cc\u0634\u0646\u0647\u0627\u062f\u06cc \u0628\u0627\u06cc\u062f 600 \u06a9\u0644\u0645\u0647 \u0628\u0627\u0634\u062f."],"URL unavailable. Add a short URL.":["URL \u062f\u0631 \u062f\u0633\u062a\u0631\u0633 \u0646\u06cc\u0633\u062a. \u06cc\u06a9 URL \u06a9\u0648\u062a\u0627\u0647 \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"Permalink should be at most 75 characters long.":["\u067e\u06cc\u0648\u0646\u062f \u06cc\u06a9\u062a\u0627 \u0628\u0627\u06cc\u062f \u062d\u062f\u0627\u06a9\u062b\u0631 75 \u06a9\u0627\u0631\u0627\u06a9\u062a\u0631 \u0628\u0627\u0634\u062f."],"It is recommended to add the focus keyword as part of one or more subheadings in the content.":["\u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc \u0634\u0648\u062f \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u0631\u0627 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u0628\u062e\u0634\u06cc \u0627\u0632 \u06cc\u06a9 \u06cc\u0627 \u0686\u0646\u062f \u0632\u06cc\u0631 \u0639\u0646\u0648\u0627\u0646 \u062f\u0631 \u0645\u062d\u062a\u0648\u0627 \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"It is recommended to add the focus keyword in the alt attribute of one or more images.":["\u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc \u0634\u0648\u062f \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u0631\u0627 \u062f\u0631 \u0648\u06cc\u0698\u06af\u06cc alt \u06cc\u06a9 \u06cc\u0627 \u0686\u0646\u062f \u062a\u0635\u0648\u06cc\u0631 \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"Great! You are linking to external resources.":["\u0639\u0627\u0644\u06cc! \u0634\u0645\u0627 \u0628\u0647 \u0645\u0646\u0627\u0628\u0639 \u062e\u0627\u0631\u062c\u06cc \u067e\u06cc\u0648\u0646\u062f \u0645\u06cc \u062f\u0647\u06cc\u062f."],"No outbound links were found. Link out to external resources.":["\u0647\u06cc\u0686 \u067e\u06cc\u0648\u0646\u062f \u062e\u0631\u0648\u062c\u06cc \u06cc\u0627\u0641\u062a \u0646\u0634\u062f. \u0628\u0647 \u0645\u0646\u0627\u0628\u0639 \u062e\u0627\u0631\u062c\u06cc \u067e\u06cc\u0648\u0646\u062f \u0628\u062f\u0647\u06cc\u062f."],"Link out to external resources.":["\u0628\u0647 \u0645\u0646\u0627\u0628\u0639 \u062e\u0627\u0631\u062c\u06cc \u0644\u06cc\u0646\u06a9 \u0628\u062f\u0647\u06cc\u062f."],"It helps visitors read more about a topic and prevents pogosticking.":["\u0627\u06cc\u0646 \u06a9\u0645\u06a9 \u0645\u06cc \u06a9\u0646\u062f \u062a\u0627 \u0628\u0627\u0632\u062f\u06cc\u062f \u06a9\u0646\u0646\u062f\u06af\u0627\u0646 \u0627\u0637\u0644\u0627\u0639\u0627\u062a \u0628\u06cc\u0634\u062a\u0631 \u062f\u0631 \u0645\u0648\u0631\u062f \u06cc\u06a9 \u0645\u0648\u0636\u0648\u0639 \u0631\u0627 \u0628\u062e\u0648\u0627\u0646\u0646\u062f \u0648 \u0627\u0632 \u067e\u06cc\u0634\u06af\u0648\u06cc\u06cc \u06a9\u0631\u062f\u0646 \u062c\u0644\u0648\u06af\u06cc\u0631\u06cc \u0645\u06cc \u06a9\u0646\u062f."],"At least one external link with DoFollow found in your content.":["\u062d\u062f\u0627\u0642\u0644 \u06cc\u06a9 \u067e\u06cc\u0648\u0646\u062f \u062e\u0627\u0631\u062c\u06cc \u0628\u0627 DoFollow \u062f\u0631 \u0645\u062d\u062a\u0648\u0627\u06cc \u0634\u0645\u0627 \u06cc\u0627\u0641\u062a \u0634\u062f\u0647 \u0627\u0633\u062a."],"Add DoFollow links pointing to external resources.":["\u067e\u06cc\u0648\u0646\u062f\u0647\u0627\u06cc DoFollow \u0631\u0627 \u0628\u0647 \u0645\u0646\u0627\u0628\u0639 \u062e\u0627\u0631\u062c\u06cc \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"PageRank Sculpting no longer works. Your posts should have a mix of nofollow and DoFollow links.":["PageRank Sculpting \u062f\u06cc\u06af\u0631 \u06a9\u0627\u0631 \u0646\u0645\u06cc \u06a9\u0646\u062f. \u0646\u0648\u0634\u062a\u0647\u200c\u0647\u0627\u06cc \u0634\u0645\u0627 \u0628\u0627\u06cc\u062f \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0627\u0632 \u067e\u06cc\u0648\u0646\u062f\u0647\u0627\u06cc nofollow \u0648 DoFollow \u0628\u0627\u0634\u062f."],"There is no ideal keyword density percentage, but it should not be too high. The most important thing is to keep the copy natural.":["\u062f\u0631\u0635\u062f \u062a\u0631\u0627\u06a9\u0645 \u0627\u06cc\u062f\u0647 \u0622\u0644 \u0628\u0631\u0627\u06cc \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0631\u062f\u060c \u0627\u0645\u0627 \u0646\u0628\u0627\u06cc\u062f \u062e\u06cc\u0644\u06cc \u0632\u06cc\u0627\u062f \u0628\u0627\u0634\u062f. \u0645\u0647\u0645\u062a\u0631\u06cc\u0646 \u0686\u06cc\u0632 \u0637\u0628\u06cc\u0639\u06cc \u0646\u06af\u0647 \u062f\u0627\u0634\u062a\u0646 \u0646\u0633\u062e\u0647 \u0627\u0633\u062a."],"You are linking to other resources on your website which is great.":["\u0634\u0645\u0627 \u062f\u0631 \u0648\u0628 \u0633\u0627\u06cc\u062a \u062e\u0648\u062f \u0628\u0647 \u0645\u0646\u0627\u0628\u0639 \u062f\u06cc\u06af\u0631 \u067e\u06cc\u0648\u0646\u062f \u0645\u06cc \u062f\u0647\u06cc\u062f \u06a9\u0647 \u0628\u0633\u06cc\u0627\u0631 \u0639\u0627\u0644\u06cc \u0627\u0633\u062a."],"We couldn't find any internal links in your content.":["\u0645\u0627 \u0646\u062a\u0648\u0627\u0646\u0633\u062a\u06cc\u0645 \u067e\u06cc\u0648\u0646\u062f\u0647\u0627\u06cc \u062f\u0627\u062e\u0644\u06cc \u0631\u0627 \u062f\u0631 \u0645\u062d\u062a\u0648\u0627\u06cc \u0634\u0645\u0627 \u067e\u06cc\u062f\u0627 \u06a9\u0646\u06cc\u0645."],"Add internal links in your content.":["\u067e\u06cc\u0648\u0646\u062f\u0647\u0627\u06cc \u062f\u0627\u062e\u0644\u06cc \u0631\u0627 \u062f\u0631 \u0645\u062d\u062a\u0648\u0627\u06cc \u062e\u0648\u062f \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"Internal links decrease your bounce rate and improve SEO.":["\u067e\u06cc\u0648\u0646\u062f\u0647\u0627\u06cc \u062f\u0627\u062e\u0644\u06cc \u0645\u06cc\u0632\u0627\u0646 \u0646\u0631\u062e \u062e\u0631\u0648\u062c \u0634\u0645\u0627 \u0631\u0627 \u06a9\u0627\u0647\u0634 \u062f\u0627\u062f\u0647 \u0648 \u0633\u0626\u0648 \u0631\u0627 \u0628\u0647\u0628\u0648\u062f \u0645\u06cc \u0628\u062e\u0634\u062f."],"You haven't used this Focus Keyword before.":["\u0642\u0628\u0644\u0627\u064b \u0627\u0632 \u0627\u06cc\u0646 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u06a9\u0631\u062f\u0647\u200c\u0627\u06cc\u062f."],"already used":["\u0642\u0628\u0644\u0627\u064b \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0634\u062f\u0647"],"Set a Focus Keyword for this content.":["\u06cc\u06a9 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0645\u062d\u062a\u0648\u0627 \u062a\u0646\u0638\u06cc\u0645 \u06a9\u0646\u06cc\u062f."],"We are searching in database.":["\u0645\u0627 \u062f\u0631 \u067e\u0627\u06cc\u06af\u0627\u0647 \u062f\u0627\u062f\u0647 \u062c\u0633\u062a\u062c\u0648 \u0645\u06cc \u06a9\u0646\u06cc\u0645."],"Focus Keyword used at the beginning of SEO title.":["\u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0627\u0628\u062a\u062f\u0627\u06cc \u0639\u0646\u0648\u0627\u0646 \u0633\u0626\u0648 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0645\u06cc \u0634\u0648\u062f."],"Focus Keyword doesn't appear at the beginning of SEO title.":["\u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0627\u0628\u062a\u062f\u0627\u06cc \u0639\u0646\u0648\u0627\u0646 \u0633\u0626\u0648 \u0638\u0627\u0647\u0631 \u0646\u0645\u06cc \u0634\u0648\u062f."],"Use the Focus Keyword near the beginning of SEO title.":["\u0627\u0632 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0627\u0628\u062a\u062f\u0627\u06cc \u0639\u0646\u0648\u0627\u0646 \u0633\u0626\u0648 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f."],"The SEO page title should contain the Focus Keyword preferably at the beginning.":["\u0639\u0646\u0648\u0627\u0646 \u0633\u0626\u0648 \u0635\u0641\u062d\u0647 \u0628\u0627\u06cc\u062f \u062f\u0631 \u0634\u0631\u0648\u0639 \u0634\u0627\u0645\u0644 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u0628\u0627\u0634\u062f."],"Your title has a positive or a negative sentiment.":["\u0639\u0646\u0648\u0627\u0646 \u0634\u0645\u0627 \u0627\u062d\u0633\u0627\u0633 \u0645\u062b\u0628\u062a \u06cc\u0627 \u0645\u0646\u0641\u06cc \u062f\u0627\u0631\u062f."],"Titles with positive or negative sentiment work best for higher CTR.":["\u0639\u0646\u0648\u0627\u0646\u200c\u0647\u0627\u06cc \u0628\u0627 \u0627\u062d\u0633\u0627\u0633\u0627\u062a \u0645\u062b\u0628\u062a \u06cc\u0627 \u0645\u0646\u0641\u06cc \u0628\u0631\u0627\u06cc CTR \u0628\u0627\u0644\u0627\u062a\u0631 \u06a9\u0627\u0631 \u0645\u06cc \u06a9\u0646\u0646\u062f."],"Headlines with a strong emotional sentiment (positive or negative) tend to receive more clicks.":["\u0639\u0646\u0648\u0627\u0646\u200c\u0647\u0627\u06cc \u0628\u0627 \u0627\u062d\u0633\u0627\u0633\u0627\u062a \u0639\u0627\u0637\u0641\u06cc (\u0645\u062b\u0628\u062a \u06cc\u0627 \u0645\u0646\u0641\u06cc) \u062a\u0645\u0627\u06cc\u0644 \u0628\u0647 \u06a9\u0644\u06cc\u06a9\u200c\u0647\u0627\u06cc \u0628\u06cc\u0634\u062a\u0631\u06cc \u062f\u0627\u0631\u0646\u062f."],"Add %s to your title to increase CTR.":["\u0628\u0631\u0627\u06cc \u0627\u0641\u0632\u0627\u06cc\u0634 CTR %s \u0631\u0627 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u062e\u0648\u062f \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"Power Words are tried-and-true words that copywriters use to attract more clicks.":["\u06a9\u0644\u0645\u0627\u062a \u0642\u0648\u06cc \u06a9\u0644\u0645\u0627\u062a \u0645\u062d\u0631\u0645\u0627\u0646\u0647 \u0648 \u0648\u0627\u0642\u0639\u06cc \u0647\u0633\u062a\u0646\u062f \u06a9\u0647 \u0646\u0648\u06cc\u0633\u0646\u062f\u06af\u0627\u0646 \u0628\u0631\u0627\u06cc \u062c\u0644\u0628 \u06a9\u0644\u06cc\u06a9\u200c\u0647\u0627\u06cc \u0628\u06cc\u0634\u062a\u0631 \u0627\u0632 \u0622\u0646\u0647\u0627 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0645\u06cc \u06a9\u0646\u0646\u062f."],"You are using a number in your SEO title.":["\u0634\u0645\u0627 \u062f\u0631 \u0639\u0646\u0648\u0627\u0646 \u0633\u0626\u0648 \u062e\u0648\u062f \u0627\u0632 \u0634\u0645\u0627\u0631\u0647 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0645\u06cc \u06a9\u0646\u06cc\u062f."],"Your SEO title doesn't contain a number.":["\u0639\u0646\u0648\u0627\u0646 \u0633\u0626\u0648 \u0634\u0645\u0627 \u0639\u062f\u062f \u0646\u062f\u0627\u0631\u062f."],"Add a number to your title to improve CTR.":["\u0628\u0631\u0627\u06cc \u0628\u0647\u0628\u0648\u062f CTR \u0639\u062f\u062f\u06cc \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u062e\u0648\u062f \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"Headlines with numbers are 36% more likely to generate clicks, according to research by Conductor.":["\u0637\u0628\u0642 \u062a\u062d\u0642\u06cc\u0642\u0627\u062a \u0627\u0646\u062c\u0627\u0645 \u0634\u062f\u0647 \u062a\u0648\u0633\u0637 Conductor\u060c \u0639\u0646\u0648\u0627\u0646\u200c\u0647\u0627\u06cc \u062f\u0627\u0631\u0627\u06cc \u0627\u0639\u062f\u0627\u062f 36% \u0627\u062d\u062a\u0645\u0627\u0644 \u0627\u06cc\u062c\u0627\u062f \u06a9\u0644\u06cc\u06a9 \u0631\u0627 \u062f\u0627\u0631\u0646\u062f."],"Use Table of Content to break-down your text.":["\u0628\u0631\u0627\u06cc \u062a\u062c\u0632\u06cc\u0647 \u0645\u062a\u0646 \u062e\u0648\u062f \u0627\u0632 Table of Content \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f."],"At least one paragraph is long. Consider using short paragraphs.":["\u062d\u062f\u0627\u0642\u0644 \u06cc\u06a9 \u067e\u0627\u0631\u0627\u06af\u0631\u0627\u0641 \u0637\u0648\u0644\u0627\u0646\u06cc \u0627\u0633\u062a. \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u067e\u0627\u0631\u0627\u06af\u0631\u0627\u0641\u200c\u0647\u0627\u06cc \u06a9\u0648\u062a\u0627\u0647 \u067e\u06cc\u0634\u0646\u0647\u0627\u062f \u0645\u06cc \u0634\u0648\u062f."],"Add short and concise paragraphs for better readability and UX.":["\u067e\u0627\u0631\u0627\u06af\u0631\u0627\u0641\u200c\u0647\u0627\u06cc \u06a9\u0648\u062a\u0627\u0647 \u0648 \u0645\u062e\u062a\u0635\u0631 \u0628\u0631\u0627\u06cc \u062e\u0648\u0627\u0646\u0627\u06cc\u06cc \u0628\u0647\u062a\u0631 \u0648 UX \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"Short paragraphs are easier to read and more pleasing to the eye. Long paragraphs scare the visitor, and they might result to SERPs looking for better readable content.":["\u067e\u0627\u0631\u0627\u06af\u0631\u0627\u0641\u200c\u0647\u0627\u06cc \u06a9\u0648\u062a\u0627\u0647 \u0631\u0627\u062d\u062a \u062a\u0631 \u0642\u0627\u0628\u0644 \u062e\u0648\u0627\u0646\u062f\u0646 \u0648 \u062f\u0644\u067e\u0630\u06cc\u0631\u062a\u0631 \u0647\u0633\u062a\u0646\u062f. \u067e\u0627\u0631\u0627\u06af\u0631\u0627\u0641 \u0637\u0648\u0644\u0627\u0646\u06cc\u060c \u0628\u0627\u0632\u062f\u06cc\u062f \u06a9\u0646\u0646\u062f\u0647 \u0631\u0627 \u0645\u06cc\u200c\u062a\u0631\u0633\u0627\u0646\u062f \u0648 \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0628\u0647 SERP \u0645\u0646\u062c\u0631 \u0634\u0648\u062f \u06a9\u0647 \u0628\u0647 \u062f\u0646\u0628\u0627\u0644 \u0645\u0637\u0627\u0644\u0628 \u062e\u0648\u0627\u0646\u062f\u0646\u06cc \u0628\u0647\u062a\u0631 \u0628\u0627\u0634\u0646\u062f."],"You are not using rich media like images or videos.":["\u0634\u0645\u0627 \u0627\u0632 \u0631\u0633\u0627\u0646\u0647\u200c\u0647\u0627\u06cc \u063a\u0646\u06cc \u0645\u0627\u0646\u0646\u062f \u062a\u0635\u0627\u0648\u06cc\u0631 \u06cc\u0627 \u0648\u06cc\u062f\u0626\u0648 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0645\u06cc \u06a9\u0646\u06cc\u062f."],"Content with images and\/or video feels more inviting to users. It also helps supplement your textual content.":["\u0645\u062d\u062a\u0648\u0627\u06cc \u062a\u0635\u0627\u0648\u06cc\u0631 \u0648\/\u06cc\u0627 \u0648\u06cc\u062f\u0626\u0648 \u0628\u0631\u0627\u06cc \u06a9\u0627\u0631\u0628\u0631\u0627\u0646 \u0628\u0633\u06cc\u0627\u0631 \u062c\u0630\u0627\u0628 \u0627\u0633\u062a. \u0647\u0645\u0686\u0646\u06cc\u0646 \u0628\u0647 \u062a\u06a9\u0645\u06cc\u0644 \u0645\u062d\u062a\u0648\u0627\u06cc \u0645\u062a\u0646\u06cc \u0634\u0645\u0627 \u06a9\u0645\u06a9 \u0645\u06cc \u06a9\u0646\u062f."],"Focus Keyword found in the subheading(s).":["\u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0632\u06cc\u0631\u0628\u062e\u0634\u200c\u0647\u0627 \u06cc\u0627\u0641\u062a \u0634\u062f."],"Focus Keyword not found in subheading(s) like H2, H3, H4, etc..":["\u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0632\u06cc\u0631\u0628\u062e\u0634\u200c\u0647\u0627 \u0645\u0627\u0646\u0646\u062f H2 \u060cH3 \u060cH4 \u0648 ... \u06cc\u0627\u0641\u062a \u0646\u0645\u06cc \u0634\u0648\u062f."],"Use Focus Keyword in subheading(s) like H2, H3, H4, etc..":["\u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0632\u06cc\u0631 \u062a\u06cc\u062a\u0631\u0647\u0627 \u0645\u0627\u0646\u0646\u062f H2 \u060cH3 \u060cH4 \u0648 ..."],"Focus Keyword found in image alt attribute(s).":["\u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0648\u06cc\u0698\u06af\u06cc alt (\u0645\u062a\u0646 \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u062a\u0635\u0627\u0648\u06cc\u0631) \u06cc\u0627\u0641\u062a \u0634\u062f."],"Focus Keyword not found in image alt attribute(s).":["\u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u062f\u0631 \u0648\u06cc\u0698\u06af\u06cc alt (\u0645\u062a\u0646 \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u062a\u0635\u0627\u0648\u06cc\u0631) \u06cc\u0627\u0641\u062a \u0646\u0634\u062f."],"Add an image with your Focus Keyword as alt text.":["\u062a\u0635\u0648\u06cc\u0631\u06cc \u0631\u0627 \u0628\u0627 \u06a9\u0644\u0645\u0647 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0635\u0644\u06cc \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u0645\u062a\u0646 alt \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."],"Your content contains images and\/or video(s).":["\u0645\u062d\u062a\u0648\u0627\u06cc \u0634\u0645\u0627 \u062d